// One-time, owner-authorized execution. Receipts prevent retries; inspect provider history before any recovery.
if (!process.argv.includes('--send')) { console.log('Execution requires --send; review the saved plan and existing receipts first.'); process.exit(0); }
import fs from 'node:fs';
const prod=JSON.parse(fs.readFileSync('/private/tmp/interaction-production-env.json'));const root='deliverables/partnership-revival-execution-2026-09-24';
const headers={apikey:prod.SUPABASE_KEY,Authorization:'Bearer '+prod.SUPABASE_KEY,'Content-Type':'application/json',Prefer:'return=representation'};
const old=JSON.parse(fs.readFileSync('/private/tmp/partnership-wide-20260924/provider-shortlist.json'));const touches=JSON.parse(fs.readFileSync('/private/tmp/partnership-wide-20260924/touches.json'));
async function db(t,q={},method='GET',body){const r=await fetch(prod.SUPABASE_URL+'/rest/v1/'+t+'?'+new URLSearchParams(q),{method,headers,body:body?JSON.stringify(body):undefined});if(!r.ok)throw Error(t+' '+r.status+' '+(await r.text()).slice(0,200));return r.json();}
const login=await fetch('https://go.quote2move.com/api/auth/login',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({password:prod.AUTH_PASSWORD})});if(!login.ok)throw Error('Login failed');const cookie=login.headers.getSetCookie().map(x=>x.split(';')[0]).join('; ');
for(const p of JSON.parse(fs.readFileSync(root+'/sms-plan.json'))){const path=root+'/'+p.id+'.json';if(fs.existsSync(path)){console.log(p.name,'existing receipt');continue;}let reserved=false;try{
 const [c]=await db('market_contacts',{id:'eq.'+p.id});if(!c||c.do_not_contact||c.cross_channel_suppressed_at||['dnc','closed_lost'].includes(c.stage)||['opted_out','rejected'].includes(c.decision))throw Error('Contact suppressed');
 const recent=await db('market_touches',{contact_id:'eq.'+p.id,order:'created_at.desc',limit:'25'});const baseline=touches.filter(x=>x.contact_id===p.id).at(-1);if(recent[0]?.id!==baseline?.id)throw Error('New CRM activity requires review');
 const current={};for(const dir of ['To','From']){const r=await fetch(`https://api.twilio.com/2010-04-01/Accounts/${prod.TWILIO_ACCOUNT_SID}/Messages.json?`+new URLSearchParams({[dir]:c.phone,PageSize:'10'}),{headers:{Authorization:'Basic '+Buffer.from(prod.TWILIO_ACCOUNT_SID+':'+prod.TWILIO_AUTH_TOKEN).toString('base64')}});if(!r.ok)throw Error('Twilio review failed');current[dir]=(await r.json()).messages;const b=old.find(x=>x.id===p.id);if(b&&b[dir]?.[0]?.sid!==current[dir][0]?.sid)throw Error('New Twilio activity requires review');if(!b&&current[dir].some(x=>new Date(x.date_created)>new Date(baseline.created_at)))throw Error('Unreviewed provider activity');}
 if(!current.From.length)throw Error('Missing inbound relationship');
 const pending=await db('sequence_jobs',{contact_id:'eq.'+p.id,status:'eq.pending',select:'id,template_key'});if(pending.some(x=>x.template_key?.startsWith('scheduled_reply:')))throw Error('Already queued reply');
 const from=/ottawa|kanata/i.test(c.city)?'+15482908695':current.From[0].to;
 const state={...p,from,to:c.phone,authorization:'User explicitly instructed sending now, overriding after-hours scheduling.',at:new Date().toISOString(),state:'reserved_do_not_retry'};fs.writeFileSync(path,JSON.stringify(state,null,2),{flag:'wx'});reserved=true;
 const r=await fetch(`https://go.quote2move.com/api/marketing/contacts/${p.id}/send-reply`,{method:'POST',headers:{Cookie:cookie,'Content-Type':'application/json'},body:JSON.stringify({body:p.body,from_number:from}),signal:AbortSignal.timeout(60000)});const txt=await r.text();let result;try{result=JSON.parse(txt);}catch{result={error:txt.slice(0,250)}}
 fs.writeFileSync(path,JSON.stringify({...state,state:r.ok?'provider_accepted':'held',result},null,2));console.log(JSON.stringify({name:p.name,ok:r.ok,result}));
 if(r.ok)await db('market_contacts',{id:'eq.'+p.id},'PATCH',{sequence_paused:true,sequence_paused_reason:'Owner-authorized contextual follow-up sent September 24; await reply.',next_follow_up:'2026-10-01'});
 }catch(e){console.log(JSON.stringify({name:p.name,error:e.message}));if(!reserved)fs.writeFileSync(path,JSON.stringify({...p,state:'held',error:e.message},null,2));}}
